async () => {
const out = {}
for (const path of ['/', '/about', '/contact', '/posts']) {
  const doc = await new Promise(res => { const f = document.createElement('iframe'); f.style.cssText='width:1440px;height:900px;position:absolute;left:-9999px'; f.src = path; f.onload = () => setTimeout(() => res(f), 1500); document.body.append(f) })
  const d = doc.contentDocument, w = doc.contentWindow
  const skies = [...d.querySelectorAll('*')].filter(e => w.getComputedStyle(e).backgroundImage.includes('svg+xml') && w.getComputedStyle(e).backgroundImage.includes('linear-gradient(rgb(6'))
  const cards = []
  for (const sky of skies) for (const e of sky.querySelectorAll('*')) {
    const cs = w.getComputedStyle(e)
    if (cs.backgroundColor !== 'rgba(0, 0, 0, 0)' && e.getBoundingClientRect().width > 200 && !e.closest('a,button,select,input,textarea') ) {
      let p = e.parentElement, nested = false
      while (p && p !== sky) { if (w.getComputedStyle(p).backgroundColor !== 'rgba(0, 0, 0, 0)') nested = true; p = p.parentElement }
      if (!nested) cards.push(`${e.tagName}.${e.className} bg=${cs.backgroundColor} border=${cs.border} radius=${cs.borderRadius}`)
    }
  }
  out[path] = { skies: skies.map(s => s.className), cards: [...new Set(cards)] }
  doc.remove()
}
const nav = document.querySelector('nav')
out.nav = `${nav.className} bg=${getComputedStyle(nav).backgroundColor} border=${getComputedStyle(nav).border} parent=${nav.parentElement.tagName}.${nav.parentElement.className}`
return out }

