.link_styles {
	text-decoration: underline;
	color: var(--font-blue);
	font-family: "Poppins-Regular", sans-serif;
	/* Shrinks a little on the narrowest phones so all three links plus the
	   theme control stay on one row down to 320px without wrapping. */
	font-size: clamp(0.75rem, 3.2vw, 0.9rem);
	text-underline-offset: 0.2em;
	/* Pad out to a comfortable tap target inside the bar. */
	display: inline-flex;
	align-items: center;
	min-height: 2.75rem;
	padding: 0 0.25rem;
	white-space: nowrap;
}

.link_styles:focus-visible {
	border-radius: 0.25rem;
	outline: 3px solid var(--focus-color);
	outline-offset: 3px;
}

