async () => {
const { food } = await (await fetch('/__food.json')).json()
const NS = 'http://www.w3.org/2000/svg'
const svg = document.createElementNS(NS, 'svg'); svg.setAttribute('width', '260'); svg.setAttribute('height', '260'); svg.style.cssText = 'position:absolute;left:-9999px'; document.body.append(svg)
const bbox = d => { const p = document.createElementNS(NS, 'path'); p.setAttribute('d', d); svg.append(p); const b = p.getBBox(); p.remove(); return b }
const groups = []
for (const subs of food) {
  const boxes = subs.map(bbox)
  const parent = subs.map((_, i) => i)
  const find = i => parent[i] === i ? i : (parent[i] = find(parent[i]))
  const hit = (a, b, m = 1) => a.x - m < b.x + b.width && b.x - m < a.x + a.width && a.y - m < b.y + b.height && b.y - m < a.y + a.height
  for (let i = 0; i < subs.length; i++) for (let j = i + 1; j < subs.length; j++) if (hit(boxes[i], boxes[j])) parent[find(i)] = find(j)
  const map = new Map()
  subs.forEach((d, i) => { const r = find(i); if (!map.has(r)) map.set(r, []); map.get(r).push(d) })
  for (const ds of map.values()) { const d = ds.join(''); const b = bbox(d); groups.push({ d, box: [Math.round(b.x), Math.round(b.y), Math.round(b.width), Math.round(b.height)] }) }
}
svg.remove()
return groups
}

