input.function:
async () => {
  const out = {}
  for (const path of ['/', '/about', '/contact', '/posts']) {
    const doc = await new Promise(res => { const f = document.createElement('iframe'); f.style.cssText='position:fixed;left:0;top:0;width:1440px;height:900px;visibility:hidden'; f.src = path; f.onload = () => setTimeout(() => res(f), 1500); document.body.appendChild(f) })
    const d = doc.contentDocument, w = doc.contentWindow
    const footer = d.querySelector('footer')
    // walk upward from just above footer top to find what's painted there
    const ft = footer.getBoundingClientRect().top + w.scrollY
    w.scrollTo(0, ft - 450)
    await new Promise(r => setTimeout(r, 200))
    const y = footer.getBoundingClientRect().top
    const probes = [1, 4, 8, 14].map(o => { const el = d.elementFromPoint(720, y - o); return `${o}px:${el?.tagName}.${(el?.className||'').toString().slice(0,40)}` })
    out[path] = { theme: d.documentElement.dataset.theme, probes }
    doc.remove()
  }
  return out
}

